import {useMemo,useState} from 'react';
import CryptoBookExamples from './CryptoBookExamples';

/* Independent, original instructional summaries. The 2018 Furneaux textbook informs
   the foundational progression; modern FATF, OSCE and protocol documentation
   inform later exercises. All people, values and transactions here are fictional. */
type Level='Foundation'|'Practitioner'|'Specialist';
type Drill={id:string;level:Level;title:string;objective:string;teach:string;analogy:string;example:string;steps:string[];question:string;options:string[];correct:number;why:string;source:string;url:string};
export const cryptoFieldDrills:Drill[]=[
{id:'language',level:'Foundation',title:'Speak cryptocurrency fluently',objective:'Explain blockchain, coin, token, wallet, address, private key and transaction hash to a non-specialist.',teach:'A blockchain stores state or transactions according to network rules. A native coin belongs to the network; a token is typically represented by a smart contract or another protocol. Wallet software manages signing capability or access to a custodian. An address is an on-chain identifier, not a confirmed person. A hash locates an event only in its relevant network context.',analogy:'A ledger is a shared record, an address is a reference number, and a wallet is the tool used to manage access. None is necessarily a physical container of coins.',example:'A witness supplies an Ethereum-looking 0x address and says it belongs to a suspect. First verify the chain, token contract and transaction before describing any transfer.',steps:['Identify the asset, chain, network ID and token contract where applicable.','Describe observations without assuming a wallet belongs to a named person.','Explain technical terms in plain language.','Record what a third party must corroborate.'],question:'What does a public blockchain address alone demonstrate?',options:['A verified legal identity','A chain-specific identifier that requires contextual attribution','The crime committed by its controller'],correct:1,why:'An address cannot establish the human controller or offence on its own.',source:'Bitcoin Developer Guides',url:'https://developer.bitcoin.org/devguide/'},
{id:'consensus',level:'Foundation',title:'Blocks, validators and finality',objective:'Distinguish proof-of-work, proof-of-stake, confirmations and finality.',teach:'Bitcoin uses proof-of-work. Ethereum Mainnet uses proof-of-stake since September 2022. A transaction seen in a pending pool does not have the same evidential status as an included or finalized transaction. Confirmation and finality semantics depend on the network.',analogy:'A draft entry awaiting approval is different from an entry formally entered in the books.',example:'A training exchange reports a pending ETH transfer. The investigator checks inclusion and finality rather than calling it settled.',steps:['Identify the specific network and its consensus mechanism.','Record whether the transaction is pending, included, finalized or failed.','Confirm timestamp basis and the block or slot.','Do not transfer Bitcoin confirmation rules mechanically to Ethereum.'],question:'What secures Ethereum Mainnet today?',options:['Proof-of-work miners','Proof-of-stake validators','A single centralized mining pool'],correct:1,why:'Ethereum moved to proof-of-stake in September 2022.',source:'Ethereum Merge',url:'https://ethereum.org/roadmap/merge/'},
{id:'keys',level:'Foundation',title:'Keys, custody and wallet types',objective:'Recognize custodial, non-custodial, hardware, software and multisignature arrangements.',teach:'Control of signing material is not the same as legal ownership. An exchange may control private keys for customers, and a contract or multisig may require several approvals. Never request actual seed phrases or private keys in AMLVERSE.',analogy:'The person holding the vault key is not necessarily the beneficial owner of its contents.',example:'An exchange confirms that its omnibus wallet handles many clients. That wallet address cannot be assigned to one customer.',steps:['Determine custodial versus non-custodial control.','Identify multisig or smart-contract authorization where observable.','Separate operational control, beneficial interest and account registration.','Escalate any real-key handling to approved specialist procedures.'],question:'A custodian controls an omnibus wallet. What follows?',options:['Every balance belongs to the custodian','Many clients may be represented by one service wallet','One address always identifies one client'],correct:1,why:'Custodial ledger balances and on-chain wallet addresses are different record systems.',source:'OSCE Crypto Crime Guide',url:'https://oceea.osce.org/oceea/587475'},
{id:'utxo',level:'Foundation',title:'Bitcoin UTXOs, fees and change',objective:'Read transaction inputs, outputs and change without double-counting.',teach:'In Bitcoin, a transaction consumes previous unspent outputs and creates new outputs. Inputs must cover outputs and transaction fees. An output returning to a likely spender-controlled address may be change, but this is a heuristic, not a verified owner identity.',analogy:'Paying a small bill with a large banknote returns change; the change is not another purchase.',example:'A synthetic input of 1.00 BTC creates 0.30 BTC payment, 0.69 BTC possible change and a 0.01 BTC fee.',steps:['List every consumed UTXO and output.','Calculate inputs minus outputs as fee.','Identify possible change using multiple clues and confidence labels.','Avoid claiming the entire input amount was paid to the beneficiary.'],question:'For the example, how much was sent as the stated payment?',options:['1.00 BTC','0.30 BTC','0.69 BTC'],correct:1,why:'The other output may be change; total input and payment are not the same.',source:'Bitcoin Transactions',url:'https://developer.bitcoin.org/devguide/transactions.html'},
{id:'account',level:'Foundation',title:'Account-based chains and token events',objective:'Differentiate ETH value transfers, contract interactions and token Transfer logs.',teach:'A successful contract call can trigger multiple token events. The top-level native asset value may be zero while a token moves. Token amounts must be normalized using contract decimals; symbols alone are not unique.',analogy:'A banking instruction can trigger several internal ledger entries even when the instruction itself carries no cash.',example:'Synthetic transaction TX-E1 calls a token contract with native ETH value 0 yet emits a 250 USDT-like token event.',steps:['Confirm chain ID and execution status.','Read native value, gas and contract address.','Inspect event logs and token decimals.','Reconcile internal movements and avoid double-counting logs.'],question:'A transaction has zero native ETH value but a token Transfer log. What is correct?',options:['No asset moved','A token transfer may have occurred','It must be a failed transaction'],correct:1,why:'Token movements can occur within contract execution without a native-value transfer.',source:'Ethereum Transactions',url:'https://ethereum.org/developers/docs/transactions/'},
{id:'explorers',level:'Practitioner',title:'Explorer verification and raw evidence',objective:'Verify network, transaction, timestamp, status and source provenance.',teach:'Blockchain explorers are interpretation interfaces. Where important, compare independent views and raw node/RPC output. Preserve the chain/network, TXID, block, time zone, query URL, collection time and relevant decoded fields. A screenshot alone may omit important context.',analogy:'An online bank statement is a convenient view; an auditor may still inspect underlying entries.',example:'Two explorers disagree on a token display name but share contract address and raw event data. The investigator records the discrepancy.',steps:['Choose a chain-appropriate explorer or self-hosted node.','Capture raw identifiers, status and contract metadata.','Cross-check a second provider or RPC for material findings.','Document differences as uncertainty.'],question:'Which identifier best distinguishes two same-ticker tokens?',options:['Ticker symbol only','Verified contract and network','Their marketing names'],correct:1,why:'Names and tickers can be duplicated; network and contract address are material identifiers.',source:'Etherscan',url:'https://etherscan.io/'},
{id:'tracing',level:'Practitioner',title:'Transaction tracing and value conservation',objective:'Trace multiple hops and reconcile amounts, branches and fees.',teach:'Follow each observed transaction edge with time, chain and amount. Funds may merge, split or commingle. A graph is a reasoning aid, not proof of beneficial ownership or exact provenance after pooled services. Avoid summing the same funds twice across hops.',analogy:'Counting a parcel at every sorting centre does not mean that many parcels were shipped.',example:'12 synthetic units flow A→B; B sends 7 to C and 4 to D. The remaining unit is not automatically a criminal fee.',steps:['Identify the initial source and exact transfer.','Trace each outgoing branch separately.','Reconcile fees and unrelated inflows before calculating balances.','Label observed, inferred and unknown links distinctly.'],question:'A→B is 12, B→C is 7, B→D is 4. What is directly observed arriving at C?',options:['23 units','12 units','7 units'],correct:2,why:'Only seven units are shown on the B→C edge.',source:'OSCE Crypto Crime Guide',url:'https://oceea.osce.org/oceea/587475'},
{id:'clustering',level:'Practitioner',title:'Clustering and attribution uncertainty',objective:'Assess common-input and change heuristics, exchange services and false positives.',teach:'Common-input clustering may suggest joint control for certain Bitcoin transactions, but CoinJoin, collaborative transactions, wallet behavior and service infrastructure create exceptions. Ethereum does not follow the same UTXO rules. Separate graph labels from provider-verified account information.',analogy:'People sharing a bus stop are not necessarily members of the same household.',example:'Two addresses co-occur as inputs; a CoinJoin-like collaborative transaction makes common ownership uncertain.',steps:['Describe the exact heuristic and its conditions.','Check transaction structure for collaborative spending.','Cross-reference independent address labels and primary records.','Record confidence and possible alternative explanations.'],question:'What is an appropriate conclusion from common-input co-spending alone?',options:['Common ownership is certain','A heuristic lead subject to exceptions','The addresses belong to an identified suspect'],correct:1,why:'Collaborative transactions and custody patterns can invalidate naive clustering.',source:'Bitcoin Developer Guides',url:'https://developer.bitcoin.org/devguide/'},
{id:'mixing',level:'Practitioner',title:'Mixers, CoinJoin and privacy services',objective:'Interpret obfuscation without treating privacy as a criminal offence.',teach:'Mixers, collaborative transactions and privacy-preserving protocols can interrupt straightforward provenance tracing. Investigators should preserve pre-event and post-event observations, timing, amounts and alternative explanations without asserting a deterministic match.',analogy:'People entering and leaving a busy station may share travel patterns without being the same individuals.',example:'A fictional mixer has 30 similar-sized withdrawals. Identifying one output as definitely belonging to one deposit is unsupported.',steps:['Identify what type of service or protocol is involved.','Document confirmed entry and exit observations separately.','Avoid claiming deterministic pairing without validated evidence.','Investigate service records or other lawful off-chain corroboration.'],question:'What does a mixer interaction prove by itself?',options:['Money laundering occurred','An interaction with a privacy-related service, subject to verification','The owner is known'],correct:1,why:'Privacy activity is not automatically illicit.',source:'FATF Virtual Assets',url:'https://www.fatf-gafi.org/en/topics/virtual-assets.html'},
{id:'bridges',level:'Practitioner',title:'Cross-chain bridges, swaps and wrapped assets',objective:'Understand why chain switching creates evidential gaps.',teach:'Bridges may lock/burn assets on one chain and release/mint representations on another. Cross-chain correlations can depend on relayer events, contract logs, timings and bridge-specific records. A deposit to a bridge is not by itself proof of a particular destination wallet.',analogy:'Leaving a parcel with a forwarding company does not independently establish its final recipient.',example:'A synthetic bridge deposit of 400 units has a later destination-chain mint, but the recipient field is missing.',steps:['Identify bridge contracts and both chain IDs.','Preserve lock/burn/mint/release transaction identifiers.','Compare bridge event identifiers and public records.','Mark missing destination attribution as unverified.'],question:'A bridge deposit is observed but the destination address is not. What is supported?',options:['The final recipient is identified','The deposit is observed; the destination remains unresolved','The same owner necessarily controls both ends'],correct:1,why:'A cross-chain transfer needs explicit matching evidence.',source:'OSCE Crypto Crime Guide',url:'https://oceea.osce.org/oceea/587475'},
{id:'defi',level:'Practitioner',title:'DeFi protocols, swaps, lending and liquidity pools',objective:'Separate contract events, pool custody and ultimate beneficiary.',teach:'A token swap can route through pools and routers with multiple transfers. Lending and liquidation events complicate simple sender→receiver assumptions. Trace the contract call and decoded events; a pool address is not necessarily the criminal beneficiary.',analogy:'Currency exchange through a bureau may involve internal inventory accounts without changing the customer’s identity.',example:'A synthetic 100-token swap interacts with two liquidity pools before crediting 98 units of another asset.',steps:['Identify protocol, router and token contract addresses.','Review call trace and event logs.','Distinguish fees, LP reserves and customer receipts.','Check approvals and transaction origin separately.'],question:'What is the most useful next step after a complex DeFi swap?',options:['Treat the router as the final beneficiary','Decode the call and transfer events','Assume all pool owners are suspects'],correct:1,why:'Contract execution and events reveal the actual transfer paths.',source:'Ethereum Smart Contracts',url:'https://ethereum.org/developers/docs/smart-contracts/'},
{id:'stablecoins',level:'Practitioner',title:'Stablecoins, issuer controls and redemption',objective:'Investigate token issuer, network, freezing capability and redemption leads.',teach:'Stablecoins may be issued on many networks and include issuer-operated administrative controls. A freeze or redemption is not automatic and requires appropriate legal authority and provider cooperation. Reserve symbols and wrapped variants may be confused.',analogy:'A privately issued voucher may be transferred among customers but redeemed or disabled under issuer rules.',example:'An analyst sees USDX on two chains and must verify both token contracts before reporting a combined total.',steps:['Verify issuer, chain and token contract.','Read transfer/mint/burn events and freeze status where applicable.','Identify exchange and redemption relationships for lawful enquiry.','Confirm any proposed preservation or freeze route with authorised counsel.'],question:'What must be checked before aggregating same-ticker stablecoin transfers?',options:['Only ticker and amount','Network, contract, decimals and issuer','Only a social media logo'],correct:1,why:'Token contracts and chain contexts may differ despite matching symbols.',source:'FATF 2026 Targeted Update',url:'https://www.fatf-gafi.org/en/publications/Fatfrecommendations/targeted-updated-virtualassets-vasps-2026.html'},
{id:'vasp',level:'Specialist',title:'VASPs, KYC and lawful international requests',objective:'Plan scoped preservation, customer identification and account-record requests.',teach:'On-chain movements to service-controlled wallets cannot reliably establish account ownership. Appropriate requests may seek relevant account identifiers, deposit attribution, customer due diligence, transaction history, linked banking activity, device data where legally obtainable, retention and time-zone details.',analogy:'A transfer to a bank branch account is not the same as evidence identifying the end customer.',example:'A training transaction reaches a known exchange deposit cluster; no client account is yet identified.',steps:['Confirm the VASP entity and jurisdiction.','Specify chain, asset, TXIDs, wallet identifiers and narrow UTC period.','Seek preservation and disclosure through applicable legal channels.','Reconcile KYC, transactions and independent records before attribution.'],question:'Which statement is justified before an exchange responds?',options:['The service endpoint is a lead; client identity is pending','The customer is definitely the sender','Every wallet using that exchange is criminal'],correct:0,why:'The customer relationship requires service-provider or other corroborating records.',source:'OSCE Crypto Crime Guide',url:'https://oceea.osce.org/oceea/587475'},
{id:'offences',level:'Specialist',title:'Crime classification and financial intelligence',objective:'Distinguish predicate crime, proceeds movement, red flags and legal elements.',teach:'Common relevant investigations include investment and romance fraud, BEC, ransomware, theft, extortion, laundering, sanctions evasion, terrorist/proliferation financing, corruption, drug trade, trafficking and market manipulation. A pattern may trigger suspicion, but an offence requires jurisdiction-specific legal elements and evidence.',analogy:'A suspicious vehicle route may justify further enquiry but is not proof of a particular criminal offence.',example:'An exchange deposit follows a victim’s payment and several hops. Establish victim testimony and false representations separately from tracing.',steps:['Identify the suspected predicate activity and affected jurisdiction.','Map evidence to offence elements and sources.','Separate suspicious indicators from established findings.','Capture alternatives, legitimate explanations and next enquiries.'],question:'A wallet interacts with a sanctioned service label. What must an analyst do?',options:['Declare a conviction','Validate the label, date, nexus and applicable legal obligations','Assume every earlier transaction is illegal'],correct:1,why:'A red flag is not a complete legal or attribution analysis.',source:'FATF 2026 Targeted Update',url:'https://www.fatf-gafi.org/en/publications/Fatfrecommendations/targeted-updated-virtualassets-vasps-2026.html'},
{id:'evidence',level:'Specialist',title:'Forensic preservation and chain of custody',objective:'Build a reproducible evidence package without unsafe private-key handling.',teach:'Record where and when data was acquired, exact URLs and API requests, source/version, chain and block identifiers, UTC timestamps, original files, hashes and transfers between custodians. Hash equality supports byte-level integrity; it does not validate a claim. Device acquisition and seizure require separate approval and security procedures.',analogy:'A sealed evidence envelope protects integrity, but does not establish that the contents tell the truth.',example:'An analyst exports a synthetic raw transaction response and hashes the original bytes; a second copy matches.',steps:['Preserve raw blockchain and off-chain records with provenance.','Create a separate read-only original and analysis copy.','Record collector, UTC, exhibits and SHA-256 digest.','Review custody transfers and explain every inference.'],question:'A matching SHA-256 digest demonstrates what?',options:['The accused is guilty','Matching bytes in the checked copies','The public webpage was truthful'],correct:1,why:'Cryptographic digests support integrity verification, not truth or guilt.',source:'OSCE Crypto Crime Guide',url:'https://oceea.osce.org/oceea/587475'},
{id:'seizure',level:'Specialist',title:'Asset identification, restraint and safe seizure planning',objective:'Recognize preservation options and risks without performing transfers.',teach:'Seizure depends on legal authority, demonstrated control, secure custody infrastructure and a specialist-approved plan. Transaction fees, token approvals, chain selection, multisig policies and contamination risks can matter. Training must never require moving real assets or revealing actual secrets.',analogy:'Seizing a bank deposit requires an order and controlled procedures, not merely knowing an account number.',example:'A fictional agency identifies tokens in a self-custody wallet but lacks legal authority and independent control evidence.',steps:['Determine ownership/control evidence and jurisdiction.','Consult legal and asset management specialists.','Select lawful preservation or restraint options.','Document approval, custody architecture and incident response before action.'],question:'What is the correct first action after finding a potential seed phrase?',options:['Paste it into an online explorer','Follow approved forensic and legal handling procedures','Send a test transfer to a personal wallet'],correct:1,why:'Private keys are sensitive and any movement can be irreversible or unlawful.',source:'OSCE Crypto Crime Guide',url:'https://oceea.osce.org/oceea/587475'},
{id:'report',level:'Specialist',title:'Expert report, confidence and courtroom explanation',objective:'Defend findings from raw facts to conclusions.',teach:'Reports should separate abstract, methodology, exhibits, findings, inferences, limitations and recommended next steps. Explain transaction model, provenance, clustering assumptions, service attribution and alternative hypotheses in language that a judge or nontechnical reviewer can follow.',analogy:'A map illustrates the journey, but the analyst must explain which roads were seen and which were guessed.',example:'The synthetic report shows 300 units entering an exchange-controlled address, while the customer remains unknown.',steps:['Create a reproducible timeline and evidence-to-claim matrix.','Present a transaction table and graph without double-counting.','Distinguish corroborated findings from hypotheses and estimates.','Recommend proportionate further enquiries.'],question:'Which is a properly qualified inference?',options:['The exchange wallet proves a named person is guilty','300 units reached a service-labelled address; account attribution needs verification','The flowchart establishes ownership'],correct:1,why:'This statement distinguishes ledger observation from human attribution.',source:'OSCE Crypto Crime Guide',url:'https://oceea.osce.org/oceea/587475'}
];
export type CryptoPattern={name:string;method:string;signals:string;response:string;limit:string};
export const cryptoPatterns:CryptoPattern[]=[
{name:'Investment and Ponzi fraud',method:'False returns, fake trading dashboards and repeated deposits',signals:'Victim deposit requests, fabricated profits, withdrawal barriers',response:'Preserve promotional material, victim payments, operator communications and on-chain routes',limit:'A high-yield investment is not by itself evidence of deception'},
{name:'Pig-butchering and romance fraud',method:'Long-term social engineering leading to crypto transfers',signals:'Relationship grooming, platform migration, fictitious investment gains',response:'Correlate victim narrative, messages, deposit addresses and exchange cash-outs',limit:'Shared wallets or scammers using aliases complicate attribution'},
{name:'Business email compromise',method:'Compromised correspondence redirects invoices to crypto or fiat ramps',signals:'Changed payment instructions and deceptive domains',response:'Correlate email headers, bank records, exchange deposits and device evidence',limit:'A crypto payment does not prove who compromised the mailbox'},
{name:'Ransomware and extortion',method:'Malware or threats demand a blockchain payment',signals:'Ransom notes, encrypted files and stated payment identifiers',response:'Secure incident evidence, transaction history and provider preservation requests',limit:'Payment is not proof of decryption or attacker identity'},
{name:'Theft and wallet drains',method:'Stolen credentials, malicious approvals, compromised devices',signals:'Unexpected authorisations, new approvals, immediate fund dispersal',response:'Examine contract approvals, event logs, device and authentication evidence',limit:'On-chain transfer alone does not explain whether access was authorised'},
{name:'Phishing and address poisoning',method:'Impersonation or look-alike addresses induce wrong transfers',signals:'Unsolicited links, similar address prefixes and altered clipboard records',response:'Reconstruct source of payment instruction and verify recipient byte-for-byte',limit:'Similarity is not conclusive proof of malicious coordination'},
{name:'SIM-swap or account takeover',method:'Unauthorised control of exchange accounts or authentication',signals:'Login/device changes, recovery requests and unexpected withdrawals',response:'Preserve authentication logs, account actions and telco evidence through lawful requests',limit:'Ownership of phone number does not prove an exchange instruction'},
{name:'DeFi exploit and oracle manipulation',method:'Protocol weaknesses or market distortions cause loss',signals:'Abnormal contract calls, rapid liquidity movements and oracle deviations',response:'Reconstruct state transitions, code versions, pricing and affected balances',limit:'Complex or profitable trades are not necessarily criminal'},
{name:'Rug pulls and token deception',method:'Misrepresentations, liquidity extraction and hidden contract permissions',signals:'Undisclosed admin controls, sudden drains, misleading claims',response:'Preserve marketing, governance, deployed bytecode and custody flows',limit:'A project failure alone does not prove fraudulent intent'},
{name:'Market manipulation and wash trading',method:'Artificial volume or coordinated market distortion',signals:'Repeated related trades, spoof-like patterns and beneficial control leads',response:'Correlate exchange order books, trader identities, timing and on-chain settlements',limit:'On-chain repetition alone may have legitimate explanations'},
{name:'Money laundering and layering',method:'Multiple swaps, hops and services obscure proceeds',signals:'Rapid dispersal, unaccounted sources and service changes',response:'Document predicate offence, value flow, corroboration and alternative explanations',limit:'Multiple transfers or privacy usage are not per se offences'},
{name:'Mixing and CoinJoin exposure',method:'Privacy-oriented transaction coordination obscures associations',signals:'Collaborative-looking inputs and equal-sized output patterns',response:'Preserve observed edges, quantify uncertainty and seek off-chain evidence',limit:'Privacy tools can have legitimate use'},
{name:'Cross-chain layering',method:'Chains, bridges and swaps complicate continuity of asset flows',signals:'Bridge deposits, same-time withdrawals and multi-network tokens',response:'Verify both chain events and bridge message/receipt identifiers',limit:'Time correlation alone cannot establish a matched recipient'},
{name:'Sanctions and proliferation financing',method:'Use of virtual assets by restricted parties or procurement networks',signals:'Validated sanctions exposure, procurement context and service involvement',response:'Check effective designation dates, applicable jurisdictions and corroborating identity',limit:'A risk label is not itself proof of a legal breach'},
{name:'Terrorist financing',method:'Fundraising, transfers or conversions associated with designated actors',signals:'Verified fundraising claims, cross-border flows and associated networks',response:'Preserve communications, donation records and authorised intelligence exchanges',limit:'Donation to a public address does not automatically establish knowledge or intent'},
{name:'Corruption and bribery',method:'Covert value transfer associated with abuse of office',signals:'Unexplained wealth, insider approvals and contract-linked transfers',response:'Join blockchain, procurement, beneficial ownership and banking records',limit:'An asset trail alone does not establish the quid pro quo'},
{name:'Drug trafficking and illicit trade',method:'Illegal-market sales settled using crypto',signals:'Marketplace orders, shipment or communication links and payment patterns',response:'Integrate lawful marketplace, logistics and financial evidence',limit:'Use of cryptocurrency or privacy tools is not proof of illicit trade'},
{name:'Trafficking and exploitation',method:'Crypto payments linked to exploitation-related businesses',signals:'Victim evidence, advertising, facilitators and repeated payments',response:'Prioritize survivor safety, lawful records, tracing and cross-border coordination',limit:'A financial pattern cannot replace victim-centered investigation'},
{name:'Cryptojacking',method:'Unauthorised use of compute resources for mining',signals:'Unexpected mining workloads, pool connections and billing spikes',response:'Preserve host and cloud audit logs, wallet/pool references and authorisation records',limit:'A mining process may be authorised in some environments'},
{name:'Fraudulent VASPs and P2P brokers',method:'Fake exchanges, unlicensed services or deceptive OTC arrangements',signals:'Customer complaints, inconsistent records and undisclosed service roles',response:'Verify regulatory status, customer ledgers, fiat settlement and beneficial ownership',limit:'Licensing breaches and fraud require separate legal analyses'}
];
type CaseFile={id:string;title:string;brief:string;records:string[];choices:string[];correct:number;explain:string;next:string;source:string};
export const cryptoCases:CaseFile[]=[
{id:'victim',title:'Victim-to-exchange tracing',brief:'A fictional victim lost 10 units to WAL-A. A→B 10; B→C 6; B→D 3. C is labelled a possible exchange service.',records:['TX-001 · Victim → WAL-A · 10 SIM · confirmed','TX-002 · WAL-A → WAL-B · 10 SIM · confirmed','TX-003 · WAL-B → WAL-C · 6 SIM · confirmed','TX-004 · WAL-B → WAL-D · 3 SIM · confirmed','WAL-C · third-party VASP label · not verified'],choices:['State that 19 units were stolen','Document 6 units on the B→C edge and verify the exchange label','Name the controller of WAL-C as the suspect'],correct:1,explain:'The transfer to C is observable, but service and customer attribution must be independently established. Do not sum every hop as fresh proceeds.',next:'Prepare a scoped provider request with network, transaction hashes and UTC period.',source:'Chapters 9–12: recovered addresses, following money and visualization'},
{id:'utxo',title:'Bitcoin payment-versus-change reconstruction',brief:'A fictional transaction spends one 1.000 BTC UTXO and creates output A 0.240 BTC and output B 0.758 BTC; the implied fee is 0.002 BTC.',records:['Input: 1.000 BTC · previously unspent output','Output A: 0.240 BTC · merchant invoice reference','Output B: 0.758 BTC · unlabeled','Difference: 0.002 BTC · mining fee'],choices:['Treat both outputs as payments to the merchant','Identify A as a documented payment, treat B as possible change pending corroboration','Assume B is a mixer'],correct:1,explain:'Only the invoice explicitly links the merchant to A. A possible change heuristic must be qualified.',next:'Compare wallet transaction history and invoice records before attributing B.',source:'Chapter 4: transactions; Chapter 10: change analysis'},
{id:'token',title:'Token transfer with zero native value',brief:'Fictional Ethereum transaction has native value 0 ETH but logs a token transfer of 500 units. The token has six decimals.',records:['Network: simulated Ethereum-compatible chain','Execution status: success','Native ETH value: 0','Transfer event: raw 500000000 base units','Token decimals: 6'],choices:['Report no transfer','Report 500 token units and preserve contract/network','Report 500000000 whole tokens'],correct:1,explain:'Token log value is scaled by decimals; the top-level native transaction value does not represent all asset movements.',next:'Verify contract address, token issuer and additional transfer logs.',source:'Chapters 4 and 7: transactions and tokens; updated account-model practice'},
{id:'bridge',title:'Cross-chain bridge with missing recipient',brief:'An investigator observes 700 units entering a bridge contract, and a similar amount appears on another chain shortly afterward without a verified message match.',records:['Chain A TX-701 · 700 units deposited','Chain B TX-799 · 696 units received · candidate only','No authenticated bridge message ID','No account or recipient confirmation'],choices:['Conclude both wallets have the same owner','Mark only deposit as confirmed and investigate bridge message evidence','Ignore chain IDs because amounts are close'],correct:1,explain:'Timing and amount similarity cannot prove a cross-chain relationship.',next:'Seek bridge event IDs, relay receipts and destination chain records.',source:'Modern addition: cross-chain analysis'},
{id:'custody',title:'Seized device and wallet artifact',brief:'A legally seized laptop image contains a wallet application and a possible key file. No specialist seizure authority has yet been approved.',records:['Forensic image reference IMG-14 · original sealed','Wallet application artefact · detected','Possible signing material · sensitive','No legal authority to initiate a transfer'],choices:['Paste the key into a free blockchain website','Preserve and document the artefact, escalate to authorised specialists','Transfer assets to an investigator wallet'],correct:1,explain:'Private key access is high risk and does not alone resolve legal ownership; preservation and approved handling come first.',next:'Prepare a custody log, legal review and asset management plan.',source:'Chapters 8, 9 and 14: wallet discovery, analysis and seizure'},
{id:'defi',title:'DeFi router and pool attribution',brief:'A synthetic swap routes deposits through a protocol router and two pools before a beneficiary receives a different asset.',records:['WAL-P → router · 100 ALPHA','Router → pool 1 · 100 ALPHA','Pool 2 → WAL-Q · 97 BETA','Contract trace shows internal calls and fees'],choices:['The router is the human beneficiary','Reconstruct call traces and final token events','All pool participants are jointly liable'],correct:1,explain:'Protocol infrastructure is not automatically the ultimate counterparty.',next:'Document call trace and reconcile fee, reserve and beneficiary events.',source:'Modern addition: DeFi forensic analysis'},
{id:'mix',title:'Post-mixer hypothesis review',brief:'A fictional deposit of 5 units enters a collaborative privacy protocol. Thirty similarly sized withdrawals appear afterward.',records:['Entry TX-M1 · 5 SIM · observed','Protocol group · 30 withdrawals · observed','Candidate output TX-M27 · timing similarity only','No deterministic pairing or identity source'],choices:['Declare TX-M27 as the same owner','Treat TX-M27 as a hypothesis and preserve uncertainty','Identify all 30 owners as criminals'],correct:1,explain:'A privacy protocol may break deterministic traceability and is not evidence of crime by itself.',next:'Seek lawful corroboration from independent non-chain sources.',source:'Chapter 10: following money, with modern collaborative transaction caveats'},
{id:'rfi',title:'International exchange request design',brief:'A fictional exchange deposit label is verified by two sources but the client account remains unidentified.',records:['Network: TRON-like training chain','Token contract: synthetic USDT representation','TX-887 · 2,500 units · confirmed','VASP attribution: independently checked','Customer identity: unknown'],choices:['Request every customer record from the exchange','Prepare a targeted lawful preservation/disclosure request','Announce the customer name on social media'],correct:1,explain:'The request must be proportional and specify identifiers, date/time, account mapping and retention needs.',next:'Coordinate with competent authorities and preserve the reply with provenance.',source:'OSCE 2025 guide: interacting with VASPs'},
{id:'typology',title:'Fraud proceeds or ordinary business?',brief:'A public wallet receives many small transfers and frequently sends funds to an exchange. The initial analyst suggests this proves money laundering.',records:['Multiple inflows · observed','VASP outflows · observed','No identified victim or criminal predicate','Possibility of lawful merchant settlement'],choices:['Report money laundering as proven','Document suspicious patterns and examine legitimate explanations and predicate evidence','Freeze all participants without authority'],correct:1,explain:'A transaction pattern may be suspicious but does not complete any offence analysis.',next:'Correlate originator, business model, complaints and legal elements.',source:'Chapter 15: crimes; FATF risk-based assessment'},
{id:'freeze',title:'Stablecoin restraint decision',brief:'A fictional issuer-controlled token linked to a fraud investigation remains at an address. The case team wants immediate restraint.',records:['Token issuer and contract · verified','Observed token balance · simulated snapshot','Probable victim funds · preliminary','No current court order or issuer notice'],choices:['Use an unapproved private key to move funds','Verify legal powers and consult issuer/specialist authorities for lawful preservation','Assume every stablecoin can be frozen'],correct:1,explain:'Issuer capabilities and freeze powers vary; legal approval and secure processes are indispensable.',next:'Prepare evidence package, ownership assessment and authorised issuer contact.',source:'Chapter 14: seizing coins; modern stablecoin considerations'}
];
const RESOURCES=[
['Bitcoin Developer Reference','https://developer.bitcoin.org/reference/','Protocol details, UTXO and raw transaction structure'],
['Bitcoin Core','https://bitcoincore.org/','Full-node software; use regtest or other authorised test environments'],
['mempool.space','https://mempool.space/','Bitcoin block and transaction explorer'],
['Blockstream Explorer','https://blockstream.info/','Independent Bitcoin explorer'],
['Etherscan','https://etherscan.io/','Ethereum transactions, logs and verified contracts'],
['Tronscan','https://tronscan.org/','TRON transaction and token records'],
['Solscan','https://solscan.io/','Solana account and transaction records'],
['Blockscout','https://www.blockscout.com/','Open-source multi-network explorer'],
['Ethereum Documentation','https://ethereum.org/developers/docs/','Accounts, transactions, events, smart contracts and consensus'],
['Remix IDE','https://remix.ethereum.org/','Local or training-network smart-contract inspection'],
['Tenderly','https://tenderly.co/','Transaction simulation and decoding; access restrictions may apply'],
['Chainabuse','https://www.chainabuse.com/','Community scam reports, not verified criminal findings'],
['WalletExplorer','https://www.walletexplorer.com/','Bitcoin clustering leads; independently validate'],
['GraphSense','https://graphsense.info/','Open-source blockchain analytics ecosystem'],
['BlockSci','https://github.com/citp/BlockSci','Research analysis tooling; check maintenance and compatibility'],
['FATF Virtual Assets','https://www.fatf-gafi.org/en/topics/virtual-assets.html','Recommendation 15 and risk-based VA/VASP supervision'],
['FATF 2026 Targeted Update','https://www.fatf-gafi.org/en/publications/Fatfrecommendations/targeted-updated-virtualassets-vasps-2026.html','Contemporary gaps: travel rule, stablecoins, P2P, offshore VASPs, DeFi'],
['OSCE Law Enforcement Guide','https://oceea.osce.org/oceea/587475','Investigative evidence, victim support, VASPs and cooperation'],
['TRM Crypto Artifact Flipbook','https://www.trmlabs.com/guides/identifying-crypto-artifacts-in-the-field-flip-book','Frontline recognition of wallet and crypto artifacts'],
['Nick Furneaux (2018), Wiley','https://www.wiley.com/','Historical course foundation; use the learner-provided legally held copy']
] as const;
const STORAGE='amlverse-crypto-investigator-v1';
function initial():string[]{try{const a=JSON.parse(localStorage.getItem(STORAGE)||'[]');return Array.isArray(a)?a.filter((v:unknown)=>typeof v==='string'):[]}catch{return []}}
type Panel='fieldbook'|'bookexamples'|'cases'|'typologies'|'resources'|'glossary';
const glossary=[['UTXO','Unspent transaction output available as an input to a future Bitcoin transaction'],['TXID','Transaction identifier within a particular chain or network'],['Mempool','Pool of pending transactions awaiting inclusion, subject to network-specific rules'],['Gas','Execution resource cost on Ethereum-like networks'],['Wallet','Software, hardware or custody arrangement managing signing or user access'],['Private key','Secret signing material; never submit real keys to training sites'],['Custodial VASP','Service that maintains customer accounts and often controls associated blockchain keys'],['Smart contract','Code deployed on a programmable blockchain'],['Token contract','On-chain contract defining or managing a specific token representation'],['Bridge','Mechanism for moving or representing value or information across chains'],['Mixer/CoinJoin','Privacy-related mechanisms that complicate straightforward flow linkage'],['Clustering','Heuristic grouping of addresses requiring documented assumptions'],['Freeze','A restraint or token-control action that depends on relevant law and technical capability'],['RFI','Scoped request for information or preservation through appropriate legal channels'],['FATF R.15','International standard covering new technologies, virtual assets and VASPs'],['Travel Rule','Originator and beneficiary information obligations applied to qualifying transfers under applicable regulations']] as const;
export default function CryptoInvestigatorAcademy(){
 const [panel,setPanel]=useState<Panel>('fieldbook');
 const [index,setIndex]=useState(0);
 const [caseIndex,setCaseIndex]=useState(0);
 const [picked,setPicked]=useState<number|null>(null);
 const [checked,setChecked]=useState(false);
 const [completed,setCompleted]=useState<string[]>(initial);
 const [filter,setFilter]=useState('');
 const [expanded,setExpanded]=useState<string|null>(null);
 const [note,setNote]=useState('');
 const [notes,setNotes]=useState<{caseId:string;text:string;time:string}[]>([]);
 const lesson=cryptoFieldDrills[index],caseFile=cryptoCases[caseIndex];
 const caseMode=panel==='cases';
 const activeId=caseMode?'case:'+caseFile.id:'lesson:'+lesson.id;
 const total=cryptoFieldDrills.length+cryptoCases.length;
 const known=useMemo(()=>new Set(completed),[completed]);
 const selectPanel=(p:Panel)=>{setPanel(p);setPicked(null);setChecked(false)};
 const go=(i:number,forCases:boolean)=>{forCases?setCaseIndex(i):setIndex(i);setPicked(null);setChecked(false)};
 function evaluate(correct:number){if(picked===null)return;setChecked(true);if(picked===correct&&!known.has(activeId)){const next=[...completed,activeId];setCompleted(next);try{localStorage.setItem(STORAGE,JSON.stringify(next))}catch{}}}
 function addNote(){if(!note.trim())return;setNotes(p=>[...p,{caseId:caseFile.id,text:note.trim(),time:new Date().toISOString()}]);setNote('')}
 function download(){const dossier={notice:'Fictional training case notes, not forensic evidence',generatedUTC:new Date().toISOString(),completed,notes};const blob=new Blob([JSON.stringify(dossier,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='AMLVERSE_crypto_training_workbook.json';a.click();URL.revokeObjectURL(u)}
 const options=caseMode?caseFile.choices:lesson.options;
 const correct=caseMode?caseFile.correct:lesson.correct;
 return <section className="cryptoinvestigator" aria-label="Cryptocurrency investigator field academy">
  <div className="riskadvancedpromo"><div><span className="eyebrow">NEW · GUIDED PRACTICAL INVESTIGATION</span><h2>Crypto Investigator Field Academy</h2><p>{cryptoFieldDrills.length} original worked lessons · {cryptoCases.length} simulated case files · {cryptoPatterns.length} criminal typologies · {RESOURCES.length} professional references. Study before answering, work without real funds and keep a case notebook.</p></div><div><strong style={{fontSize:26}}>{completed.length}/{total}</strong><p>Fieldbook checkpoints completed</p></div></div>
  <nav className="riskadvancednav" aria-label="Cryptocurrency field academy sections">
  {([['fieldbook','Worked lessons'],['bookexamples','Book examples (30)'],['cases','Investigation simulator'],['typologies','Crime typologies'],['resources','Tools and references'],['glossary','Crypto language']] as [Panel,string][]).map(([id,label])=><button type="button" key={id} className={panel===id?'active':''} onClick={()=>selectPanel(id)}>{label}</button>)}
  </nav>
  {(panel==='fieldbook'||panel==='cases')?<div className="cryptoinvestigator-grid">
   <aside className="cryptoinvestigator-menu" aria-label="Choose exercise">
    {(caseMode?cryptoCases:cryptoFieldDrills).map((x,i)=><button key={x.id} type="button" className={i===(caseMode?caseIndex:index)?'active':''} onClick={()=>go(i,caseMode)}>{known.has((caseMode?'case:':'lesson:')+x.id)?'✓ ':''}{i+1}. {x.title}</button>)}
   </aside>
   <article className="cryptoinvestigator-work">
    <span className="eyebrow">{caseMode?'CASE SIMULATION '+(caseIndex+1)+'/'+cryptoCases.length:lesson.level+' · WORKED LESSON '+(index+1)+'/'+cryptoFieldDrills.length}</span>
    <h3>{caseMode?caseFile.title:lesson.title}</h3>
    {caseMode?<><p><strong>Scenario:</strong> {caseFile.brief}</p><div className="cryptoinvestigator-evidence"><strong>Simulated investigation browser · evidence records</strong>{caseFile.records.map((x,i)=><div key={i}><span>EXH-{String(i+1).padStart(2,'0')}</span> {x}</div>)}</div><p><strong>What should the investigator do?</strong></p></>:<><p><strong>Learning objective:</strong> {lesson.objective}</p><p>{lesson.teach}</p><div className="knowledgeexample"><strong>Analogy</strong><p>{lesson.analogy}</p><strong>Worked example</strong><p>{lesson.example}</p></div><strong>Investigation workflow</strong><ol>{lesson.steps.map(x=><li key={x}>{x}</li>)}</ol><p><a href={lesson.url} target="_blank" rel="noopener noreferrer">Further reading: {lesson.source} ↗</a></p><details className="cryptobookinline"><summary>Study textbook worked examples related to this lesson</summary><CryptoBookExamples lessonId={lesson.id} compact/></details><p><strong>Now demonstrate your understanding:</strong> {lesson.question}</p></>}
    <div className="choices">{options.map((o,i)=><button type="button" key={o} className={'choice'+(picked===i?' picked':'')+(checked&&i===correct?' correct':'')} onClick={()=>{setPicked(i);setChecked(false)}} aria-pressed={picked===i}><span className="letter">{String.fromCharCode(65+i)}</span>{o}</button>)}</div>
    <div className="actions"><button type="button" className="primary" disabled={picked===null} onClick={()=>evaluate(correct)}>Check investigative decision →</button><button type="button" className="secondary" onClick={()=>go((caseMode?caseIndex+1:index+1)%(caseMode?cryptoCases.length:cryptoFieldDrills.length),caseMode)}>Next {caseMode?'case':'lesson'} →</button></div>
    {checked?<div role="status" className="feedback"><strong>{picked===correct?'✓ Correct, competence checkpoint saved':'Review this response and try again'}</strong><p>{caseMode?caseFile.explain:lesson.why}</p>{caseMode?<p><strong>Recommended next step:</strong> {caseFile.next}</p>:null}</div>:null}
    {caseMode?<div className="cryptoinvestigator-notes"><label htmlFor="crypto-case-note">Investigator's notebook — observations, uncertainty and lawful next actions</label><textarea id="crypto-case-note" rows={4} value={note} onChange={e=>setNote(e.target.value)} placeholder="Record a fictional finding and the evidence that supports or limits it."/><div className="actions"><button type="button" className="secondary" disabled={!note.trim()} onClick={addNote}>Save case note</button><button type="button" className="secondary" disabled={!notes.length} onClick={download}>Export training dossier ({notes.length})</button></div></div>:null}
   </article>
   </div>:null}
  {panel==='bookexamples'?<CryptoBookExamples/>:null}
  {panel==='typologies'?<><h3>Offence and criminal-method reference</h3><p>A typology is not automatically an offence. Relevant criminal law, jurisdiction, evidence of conduct and requisite intent must be assessed separately.</p><label className="cryptoinvestigator-search">Filter crime patterns<input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Fraud, laundering, ransomware, DeFi, trafficking…"/></label><div className="cryptoinvestigator-patterns">{cryptoPatterns.filter(x=>[x.name,x.method,x.signals].join(' ').toLowerCase().includes(filter.toLowerCase())).map(x=><article key={x.name}><h4>{x.name}</h4><p><b>Method:</b> {x.method}</p><p><b>Investigative indicators:</b> {x.signals}</p><button type="button" className="secondary" onClick={()=>setExpanded(expanded===x.name?null:x.name)}>{expanded===x.name?'Hide response':'Investigator strategy & limitation'}</button>{expanded===x.name?<div><p><b>Strategy:</b> {x.response}</p><p><b>Important limitation:</b> {x.limit}</p></div>:null}</article>)}</div></>:null}
  {panel==='resources'?<><h3>Professional tool and standards directory</h3><p>Tools provide leads and technical views; they do not substitute for forensic documentation, legal authority or independent checks. Free tiers, service availability and terms can change. Do not paste confidential case identifiers or private keys into external services without approval.</p><div className="cryptoinvestigator-patterns">{RESOURCES.map(([name,url,reason])=><article key={name}><h4><a href={url} target="_blank" rel="noopener noreferrer">{name} ↗</a></h4><p>{reason}</p></article>)}</div></>:null}
  {panel==='glossary'?<><h3>Learn to speak crypto professionally</h3><p>Explain technical vocabulary aloud before using it in an intelligence report or legal request. Learn the difference between an address, an account, a wallet and a human operator.</p><div className="cryptoinvestigator-patterns">{glossary.map(([term,definition])=><article key={term}><h4>{term}</h4><p>{definition}</p></article>)}</div></>:null}
  <p className="notice">Educational boundary: AMLVERSE simulates blockchain evidence and investigative decisions. No live wallets, transfers, real private keys, evidence seizure or external account access are performed. Content is original instruction informed by Nick Furneaux's 2018 textbook and separately updated public standards. It is not a substitute for local law or an accredited qualification.</p>
 </section>
}
